lemma sobolevNormSqDistrib_mono {s t : ℝ} {φ : TrigPolyDual n}
    (hφ : MemSobolevDistrib n t φ) (hst : s ≤ t) :
    sobolevNormSqDistrib n s φ ≤ sobolevNormSqDistrib n t φ

lemma periodicExtension_contDiff {φ : (Fin n → ℝ) → ℂ}
    (hsmooth : ContDiff ℝ ∞ φ) (hsupp : HasCompactSupport φ) :
    ContDiff ℝ ∞ (periodicExtension n φ)

lemma periodicExtension_im_zero {φ : (Fin n → ℝ) → ℂ}
    (hsupp : HasCompactSupport φ) (him : ∀ x, (φ x).im = 0) :
    ∀ y, (periodicExtension n φ y).im = 0

lemma periodicExtension_re_nonneg {φ : (Fin n → ℝ) → ℂ}
    (hsupp : HasCompactSupport φ) (hnn : ∀ x, 0 ≤ (φ x).re) :
    ∀ y, 0 ≤ (periodicExtension n φ y).re

lemma IsInjRealizable.toIsRealizable {n : ℕ}
    {g : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    (hg : IsInjRealizable g) : IsRealizable g

lemma IsPosDefSmoothMetric.toIsSmoothMetric {n : ℕ}
    {g : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    (hg : IsPosDefSmoothMetric g) : IsSmoothMetric g

theorem periodicMatrixExt_eq_of_mem {G : (Fin N → ℝ) → Matrix (Fin N) (Fin N) ℝ}
    (hsupp : ∀ y, G y - 1 ≠ 0 → y ∈ openCube N) {x : Fin N → ℝ} (hx : ∀ j, |x j| ≤ Real.pi) :
    periodicMatrixExt N G x = G x

theorem periodicMatrixExt_posDef {G : (Fin N → ℝ) → Matrix (Fin N) (Fin N) ℝ}
    (hsupp : ∀ y, G y - 1 ≠ 0 → y ∈ openCube N) (hG : ∀ y, (G y).PosDef) (x : Fin N → ℝ) :
    (periodicMatrixExt N G x).PosDef

theorem periodicMatrixExt_smoothPeriodic {G : (Fin N → ℝ) → Matrix (Fin N) (Fin N) ℝ}
    (hG : ContDiff ℝ ∞ G) (hsupp : HasCompactSupport fun y => G y - 1) :
    SmoothPeriodic (periodicMatrixExt N G)

theorem realizes_fderiv_dot {n q : ℕ} {v : (Fin n → ℝ) → (Fin q → ℝ)}
    {g : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ} (hv : Realizes v g) (x a b : Fin n → ℝ) :
    (fderiv ℝ v x a) ⬝ᵥ (fderiv ℝ v x b) = a ⬝ᵥ (g x).mulVec b

theorem fourierSynthesis_contDiff (hn : 0 < n) {a : (Fin n → ℤ) → ℂ}
    (ha : IsRapidDecay n a) :
    ContDiff ℝ ∞ (fourierSynthesis n a)

theorem partialDeriv_fourierSynthesis (hn : 0 < n) {a : (Fin n → ℤ) → ℂ}
    (ha : IsRapidDecay n a) (j : Fin n) :
    partialDeriv j (fourierSynthesis n a) = fourierSynthesis n (partialCoeff j a)

lemma summable_norm_seqConv {a b : (Fin n → ℤ) → ℂ}
    (ha : Summable (fun m => ‖a m‖)) (hb : Summable (fun m => ‖b m‖)) :
    Summable (fun m => ‖seqConv a b m‖)

lemma fourierSynthesis_add' {a b : (Fin n → ℤ) → ℂ}
    (ha : Summable (fun m => ‖a m‖)) (hb : Summable (fun m => ‖b m‖)) :
    fourierSynthesis n (fun m => a m + b m) = fun θ => fourierSynthesis n a θ + fourierSynthesis n b θ

lemma fourierSynthesis_finset_sum {ι : Type*} (S : Finset ι) {a : ι → (Fin n → ℤ) → ℂ}
    (ha : ∀ i ∈ S, Summable (fun m => ‖a i m‖)) :
    fourierSynthesis n (fun m => ∑ i ∈ S, a i m) = fun θ => ∑ i ∈ S, fourierSynthesis n (a i) θ

lemma fourierSynthesis_sub {a b : (Fin n → ℤ) → ℂ}
    (ha : Summable (fun m => ‖a m‖)) (hb : Summable (fun m => ‖b m‖)) :
    fourierSynthesis n (fun m => a m - b m) = fun θ => fourierSynthesis n a θ - fourierSynthesis n b θ

lemma MemSobolevDistrib.sub {s : ℝ} {a b : TrigPolyDual n}
    (ha : MemSobolevDistrib n s a) (hb : MemSobolevDistrib n s b) :
    MemSobolevDistrib n s (a - b)

lemma adjugate_contDiff {M : (Fin n → ℝ) → Matrix ι ι ℝ}
    (hM : ∀ i j, ContDiff ℝ ∞ (fun x => M x i j)) (i j : ι) :
    ContDiff ℝ ∞ (fun x => (M x).adjugate i j)

lemma det_contDiff {M : (Fin n → ℝ) → Matrix ι ι ℝ}
    (hM : ∀ i j, ContDiff ℝ ∞ (fun x => M x i j)) :
    ContDiff ℝ ∞ (fun x => (M x).det)

theorem dualFrame_contDiff {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : IsPointwiseLinIndep e) (hs : ∀ i, ContDiff ℝ ∞ (e i)) (i : ι) :
    ContDiff ℝ ∞ (dualFrame e i)

theorem dualFrame_dotProduct {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : IsPointwiseLinIndep e) (i j : ι) (x : Fin n → ℝ) :
    dualFrame e i x ⬝ᵥ e j x = if i = j then 1 else 0

theorem dualFrame_smoothPeriodic {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : IsPointwiseLinIndep e) (hsp : ∀ i, SmoothPeriodic (e i)) (i : ι) :
    SmoothPeriodic (dualFrame e i)

lemma gramMatrix_contDiff {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : ∀ i, ContDiff ℝ ∞ (e i)) (i j : ι) :
    ContDiff ℝ ∞ (fun x => gramMatrix e x i j)

lemma gramMatrix_periodic {e : ι → (Fin n → ℝ) → (Fin N → ℝ)}
    (he : ∀ i, IsPeriodic2Pi (e i)) (x : Fin n → ℝ) (k : Fin n → ℤ) :
    gramMatrix e (x + periodicShift n k) = gramMatrix e x

lemma inv_contDiff {M : (Fin n → ℝ) → Matrix ι ι ℝ}
    (hM : ∀ i j, ContDiff ℝ ∞ (fun x => M x i j)) (hdet : ∀ x, (M x).det ≠ 0) (i j : ι) :
    ContDiff ℝ ∞ (fun x => (M x)⁻¹ i j)

lemma contDiff_dotProduct {N : ℕ} {u v : (Fin n → ℝ) → (Fin N → ℝ)}
    (hu : ContDiff ℝ ∞ u) (hv : ContDiff ℝ ∞ v) :
    ContDiff ℝ ∞ (fun y => u y ⬝ᵥ v y)

lemma pderiv_dotProduct {N : ℕ} {u v : (Fin n → ℝ) → (Fin N → ℝ)}
    (hu : ContDiff ℝ ∞ u) (hv : ContDiff ℝ ∞ v) (i : Fin n) (x : Fin n → ℝ) :
    pderiv i (fun y => u y ⬝ᵥ v y) x = pderiv i u x ⬝ᵥ v x + u x ⬝ᵥ pderiv i v x

lemma vecNormSq_finset_sum_le {ι : Type*} {s : ℝ} (S : Finset ι) {v : ι → VecSeq n N}
    (hv : ∀ i ∈ S, VMem n N s (v i)) :
    vecNormSq n N s (∑ i ∈ S, v i) ≤ S.card * ∑ i ∈ S, vecNormSq n N s (v i)

lemma ScalarTame.add {r : ℕ} {Q₁ Q₂ : VecSeq n N → VecSeq n N → Seq n} {A₁ A₂ : ℝ} {B₁ B₂ : ℕ → ℝ}
    (h₁ : ScalarTame n N r Q₁ A₁ B₁) (h₂ : ScalarTame n N r Q₂ A₂ B₂) :
    ScalarTame n N r (fun v w m => Q₁ v w m + Q₂ v w m) (2 * (A₁ + A₂)) (fun k => 2 * (B₁ k + B₂ k))

lemma VecTame.add {r : ℕ} {Q₁ Q₂ : VecSeq n N → VecSeq n N → VecSeq n N} {A₁ A₂ : ℝ} {B₁ B₂ : ℕ → ℝ}
    (h₁ : VecTame n N r Q₁ A₁ B₁) (h₂ : VecTame n N r Q₂ A₂ B₂) :
    VecTame n N r (fun v w => Q₁ v w + Q₂ v w) (2 * (A₁ + A₂)) (fun k => 2 * (B₁ k + B₂ k))

lemma lower_mono {r k : ℕ} (hk : r ≤ k) {v w : VecSeq n N}
    (hv : VMem n N (k + 1 : ℕ) v) (hw : VMem n N (k + 1 : ℕ) w) :
    lower n N r k v w ≤ lower n N r (k + 1) v w

lemma vecNormSq_mul_le_top {r k : ℕ} (hk : r ≤ k) {v w : VecSeq n N}
    (hv : VMem n N k v) (hw : VMem n N k w) :
    vecNormSq n N r v * vecNormSq n N r w ≤ top n N r k v w

lemma SmoothPeriodic.dotProduct {u w : (Fin n → ℝ) → (Fin N → ℝ)}
    (hu : SmoothPeriodic u) (hw : SmoothPeriodic w) :
    SmoothPeriodic (fun x => u x ⬝ᵥ w x)

@[fun_prop]
theorem contDiff_matrix {n : ℕ} {g : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    (h : ∀ i j, ContDiff ℝ ∞ fun x => g x i j) : ContDiff ℝ ∞ g

theorem injRealizable_posDef {n : ℕ}
    {g : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    (hg : IsInjRealizable g) : IsPosDefSmoothMetric g

theorem injRealizable_promotion {n : ℕ}
    {g₁ g₂ : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    (h₁ : IsInjRealizable g₁) (h₂ : IsRealizable g₂) :
    IsInjRealizable (g₁ + g₂)

lemma linearIndependent_of_append_proj {n N₁ N₂ : ℕ}
    {f₁ : Fin n → Fin N₁ → ℝ} {f₂ : Fin n → Fin N₂ → ℝ}
    (hli : LinearIndependent ℝ f₁) :
    LinearIndependent ℝ (fun i => Fin.append (f₁ i) (f₂ i))

lemma partialDeriv_concat {n N₁ N₂ : ℕ}
    {u₁ : (Fin n → ℝ) → (Fin N₁ → ℝ)} {u₂ : (Fin n → ℝ) → (Fin N₂ → ℝ)}
    (hd₁ : ContDiff ℝ ∞ u₁) (hd₂ : ContDiff ℝ ∞ u₂)
    (i : Fin n) (x : Fin n → ℝ) :
    partialDeriv i (fun x => Fin.append (u₁ x) (u₂ x)) x =
    Fin.append (partialDeriv i u₁ x) (partialDeriv i u₂ x)

lemma partialDeriv_concat_castAdd {n N₁ N₂ : ℕ}
    {u₁ : (Fin n → ℝ) → (Fin N₁ → ℝ)} {u₂ : (Fin n → ℝ) → (Fin N₂ → ℝ)}
    (hd₁ : ContDiff ℝ ∞ u₁) (hd₂ : ContDiff ℝ ∞ u₂)
    (i : Fin n) (x : Fin n → ℝ) (j : Fin N₁) :
    partialDeriv i (fun x => Fin.append (u₁ x) (u₂ x)) x (Fin.castAdd N₂ j) =
    partialDeriv i u₁ x j

theorem posDefSmoothMetric_add {n : ℕ}
    {g g' : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    (hg : IsPosDefSmoothMetric g) (hg' : IsPosDefSmoothMetric g') :
    IsPosDefSmoothMetric (g + g')

theorem posDefSmoothMetric_pos_smul {n : ℕ}
    {g : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ} {t : ℝ}
    (hg : IsPosDefSmoothMetric g) (ht : 0 < t) :
    IsPosDefSmoothMetric (t • g)

theorem realizable_finComb {n M : ℕ}
    {g : Fin M → (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    {t : Fin M → ℝ} {y : Fin M → (Fin n → ℝ)}
    (hg : ∀ α, IsRealizable (g α))
    (ht : ∀ α, 0 ≤ t α) :
    IsRealizable (∑ α : Fin M, t α • translate (y α) (g α))

theorem realizable_nonneg_smul {n : ℕ}
    {g : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ} {t : ℝ}
    (hg : IsRealizable g) (ht : 0 ≤ t) :
    IsRealizable (t • g)

theorem realizable_sum {n : ℕ}
    {g₁ g₂ : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    (h₁ : IsRealizable g₁) (h₂ : IsRealizable g₂) :
    IsRealizable (g₁ + g₂)

theorem realizable_translate {n : ℕ}
    {g : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ} {y : Fin n → ℝ}
    (hg : IsRealizable g) :
    IsRealizable (translate y g)

theorem exists_delta_posDef_sub {g g₀ : (Fin n → ℝ) → Matrix (Fin n) (Fin n) ℝ}
    (hg : IsPosDefSmoothMetric g) (hg₀ : SmoothPeriodic g₀) (hsymm : ∀ x, (g₀ x).IsSymm) :
    ∃ δ : ℝ, 0 < δ ∧ IsPosDefSmoothMetric (g - δ • g₀)

lemma pderiv_comp_scalar {n : ℕ} {g : ℝ → ℝ} {g' : ℝ} {c : (Fin n → ℝ) → ℝ}
    {c' : (Fin n → ℝ) →L[ℝ] ℝ} (a : Fin n) (x : Fin n → ℝ) (hg : HasDerivAt g g' (c x))
    (hc : HasFDerivAt c c' x) : pderiv a (fun y => g (c y)) x = g' * pderiv a c x

lemma pderiv_const_mul {n : ℕ} {f : (Fin n → ℝ) → ℝ} {f' : (Fin n → ℝ) →L[ℝ] ℝ}
    {x : Fin n → ℝ} (c : ℝ) (hf : HasFDerivAt f f' x) (a : Fin n) :
    pderiv a (fun y => c * f y) x = c * pderiv a f x

lemma pderiv_pi_apply {n N : ℕ} {f : (Fin n → ℝ) → (Fin N → ℝ)}
    (hf : ∀ m, Differentiable ℝ (fun y => f y m)) (a : Fin n) (x : Fin n → ℝ) (m : Fin N) :
    pderiv a f x m = pderiv a (fun y => f y m) x
